import React from 'react';

const features = [
  { icon: "🚀", title: "Lightning Fast", description: "Optimized for speed with lazy loading and code splitting." },
  { icon: "🔒", title: "Secure by Default", description: "Built-in authentication, RLS policies, and encryption." },
  { icon: "📱", title: "Fully Responsive", description: "Looks great on every device, from mobile to desktop." },
  { icon: "🎨", title: "Customizable", description: "Theming support with dark/light modes and design tokens." },
  { icon: "⚡", title: "Real-time", description: "Live updates with WebSocket connections and subscriptions." },
  { icon: "🤖", title: "AI Powered", description: "Integrated AI features for smarter user experiences." },
];

const FeaturesGrid = () => (
  <section className="py-20 px-6 bg-background">
    <div className="max-w-6xl mx-auto">
      <div className="text-center mb-16">
        <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">Everything You Need</h2>
        <p className="text-lg text-muted-foreground max-w-2xl mx-auto">Powerful features to help you build, deploy, and scale your applications.</p>
      </div>
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {features.map((f, i) => (
          <div key={i} className="p-6 rounded-2xl border border-border bg-card hover:shadow-lg transition-all">
            <div className="text-4xl mb-4">{f.icon}</div>
            <h3 className="text-xl font-semibold text-foreground mb-2">{f.title}</h3>
            <p className="text-muted-foreground">{f.description}</p>
          </div>
        ))}
      </div>
    </div>
  </section>
);

export default FeaturesGrid;

import React, { createContext, useContext, ReactNode, useState, useEffect } from 'react';

type AuthContextType = {
  isAuthenticated: boolean;
  user: User | null;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  loading: boolean;
};

type User = {
  email: string;
  name: string;
};

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check for existing session
    const checkSession = async () => {
      try {
        const session = localStorage.getItem('session');
        if (session) {
          // In a real app, verify session with backend
          const parsed = JSON.parse(session);
          setUser({ email: parsed.email, name: parsed.name });
        }
      } catch (error) {
        localStorage.removeItem('session');
      } finally {
        setLoading(false);
      }
    };

    checkSession();
  }, []);

  const login = async (email: string, password: string) => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 500));

    if (email && password) {
      const userData = { email, name: email.split('@')[0] };
      localStorage.setItem('session', JSON.stringify(userData));
      setUser(userData);
    } else {
      throw new Error('Invalid credentials');
    }
  };

  const logout = () => {
    localStorage.removeItem('session');
    setUser(null);
  };

  return (
    <AuthContext.Provider 
      value={{
        isAuthenticated: !!user,
        user,
        login,
        logout,
        loading
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';

const LoginForm = () => {
  const { login, loading } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await login(email, password);
    } catch (err) {
      setError('Invalid email or password');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-6">
      <div className="w-full max-w-md space-y-8">
        <div className="text-center">
          <h1 className="text-3xl font-bold text-foreground">Welcome back</h1>
          <p className="text-muted-foreground mt-2">Sign in to your account</p>
        </div>
        {error && (
          <div className="p-4 text-sm text-red-500 bg-red-50 rounded-lg">
            {error}
          </div>
        )}
        <form className="space-y-4" onSubmit={handleSubmit}>
          <div>
            <label className="block text-sm font-medium text-foreground mb-1.5">Email</label>
            <input 
              type="email" 
              className="w-full px-4 py-3 rounded-xl border border-border bg-background text-foreground"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-foreground mb-1.5">Password</label>
            <input 
              type="password" 
              className="w-full px-4 py-3 rounded-xl border border-border bg-background text-foreground"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button 
            type="submit" 
            className="w-full py-3 bg-primary text-primary-foreground font-semibold rounded-xl hover:opacity-90 transition-all flex items-center justify-center"
            disabled={loading}
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;

import React, { useState } from 'react';

const faqs = [
  { q: "How do I get started?", a: "Sign up for a free account, create a new project, and start building with AI-powered assistance." },
  { q: "Is there a free plan?", a: "Yes! Our Starter plan is completely free and includes one project with basic features." },
  { q: "Can I use my own domain?", a: "Absolutely. Pro and Enterprise plans support custom domains with automatic SSL." },
  { q: "Do you support team collaboration?", a: "Yes, our Pro plan includes real-time collaboration features for teams of any size." },
];

const FAQSection = () => {
  const [openIndex, setOpenIndex] = useState<number | null>(null);

  return (
    <section className="py-20 px-6 bg-background">
      <div className="max-w-3xl mx-auto">
        <div className="text-center mb-16">
          <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">Frequently Asked Questions</h2>
        </div>
        <div className="space-y-4">
          {faqs.map((faq, i) => (
            <div key={i} className="border border-border rounded-xl overflow-hidden">
              <button
                onClick={() => setOpenIndex(openIndex === i ? null : i)}
                className="w-full flex items-center justify-between p-5 text-left text-foreground font-medium hover:bg-muted/50 transition-colors"
              >
                {faq.q}
                <span className={`transition-transform ${openIndex === i ? 'rotate-180' : ''}`}>▼</span>
              </button>
              {openIndex === i && (
                <div className="px-5 pb-5 text-muted-foreground">{faq.a}</div>
              )}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default FAQSection;

function RichTextEditor() {
  const [content, setContent] = React.useState("<p>Start typing...</p>");
  const [isBold, setIsBold] = React.useState(false);
  const [isItalic, setIsItalic] = React.useState(false);

  return (
    <div className="border rounded-lg overflow-hidden">
      <div className="flex items-center gap-1 p-2 border-b bg-gray-50">
        <button 
          onClick={() => setIsBold(!isBold)}
          className={`p-1.5 rounded hover:bg-gray-200 ${isBold ? 'bg-gray-200 font-bold' : ''}`}
        >
          <strong>B</strong>
        </button>
        <button 
          onClick={() => setIsItalic(!isItalic)}
          className={`p-1.5 rounded hover:bg-gray-200 ${isItalic ? 'bg-gray-200 italic' : ''}`}
        >
          <em>I</em>
        </button>
        <button className="p-1.5 rounded hover:bg-gray-200 underline">U</button>
        <div className="w-px h-5 bg-gray-300 mx-1" />
        <button className="p-1.5 rounded hover:bg-gray-200 text-sm">H1</button>
        <button className="p-1.5 rounded hover:bg-gray-200 text-sm">H2</button>
      </div>
      <div 
        contentEditable
        className="min-h-[200px] p-4 outline-none prose prose-sm"
        style={{ fontWeight: isBold ? 'bold' : 'normal', fontStyle: isItalic ? 'italic' : 'normal' }}
        dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(content) }}
      />
    </div>
  );
}

function DataGrid() {
