          <tbody>
            {rowData.map((row, i) => (
              <tr key={i} className="border-b hover:bg-gray-50">
                <td className="p-2">{row.make}</td>
                <td className="p-2">{row.model}</td>
                <td className="p-2">${row.price.toLocaleString()}</td>
