function loadScript(sources, label) {
  return new Promise(function(resolve, reject) {
    var idx = 0;
    var timer;
    function tryNext() {
      if (idx >= sources.length) { clearTimeout(timer); reject(new Error('Failed to load ' + label + ' from all CDN sources')); return; }
      var s = document.createElement('script');
      s.src = sources[idx];
      s.onload = function() { clearTimeout(timer); resolve(); };
      s.onerror = function() { idx++; tryNext(); };
      document.head.appendChild(s);
    }
    timer = setTimeout(function() { reject(new Error(label + ' load timed out')); }, 3000);
    tryNext();
  });
}

(function() {
  const originalConsole = {
    log: console.log,
    info: console.info,
    warn: console.warn,
    error: console.error,
    debug: console.debug
  };

  function formatArgs(args) {
    return args.map(arg => {
      if (arg === null) return 'null';
      if (arg === undefined) return 'undefined';
      if (typeof arg === 'object') {
        try {
          return JSON.stringify(arg, null, 2);
        } catch (e) {
          return String(arg);
        }
      }
      return String(arg);
    }).join(' ');
  }

  ['log', 'info', 'warn', 'error', 'debug'].forEach(level => {
    console[level] = (...args) => {
      window.parent.postMessage({
        type: 'console',
        level: level,
        message: formatArgs(args)
      }, '*');
      originalConsole[level].apply(console, args);
    };
  });

  // Also capture uncaught errors with better diagnostics
  window.onerror = (message, source, lineno, colno, error) => {
    // Detect generic cross-origin "Script error" and provide actionable info
    var msg = String(message);
    if (msg === 'Script error.' || (msg === 'Script error' && lineno === 0 && colno === 0)) {
      msg = 'Script error (cross-origin): A generated file may contain external script tags or CDN loaders that are blocked in the preview sandbox. Try regenerating without external scripts.';
    } else {
      msg = 'Uncaught Error: ' + message + ' at ' + (source || 'unknown') + ':' + lineno + ':' + colno;
    }
    window.parent.postMessage({
      type: 'console',
      level: 'error',
      message: msg
    }, '*');
    // Unblock parent spinner — preview will not become "ready" after a fatal error
    if (!window.__done) {
      window.__done = true;
      try { window.parent.postMessage({ type: 'preview-ready' }, '*'); } catch(e) {}
    }
    return false;
  };

  window.addEventListener('unhandledrejection', (event) => {
    window.parent.postMessage({
      type: 'console',
      level: 'error',
      message: `Unhandled Promise Rejection: ${event.reason}`
    }, '*');
    if (!window.__done) {
      window.__done = true;
      try { window.parent.postMessage({ type: 'preview-ready' }, '*'); } catch(e) {}
    }
  });

  // Collect runtime errors for auto-fix reporting
  window.__previewErrors = [];
  var _origOnerror = window.onerror;
  window.onerror = function(message, source, lineno, colno, error) {
    window.__previewErrors.push(String(message) + (source ? ' at ' + source + ':' + lineno : ''));
    if (_origOnerror) return _origOnerror.apply(this, arguments);
    return false;
  };
  window.addEventListener('unhandledrejection', function(event) {
    window.__previewErrors.push('Unhandled rejection: ' + String(event.reason));
  });

  // Plain anchor tags with a root-relative href (and <form> posts) generated
  // by models must stay inside Instant Preview instead of escaping the
  // srcdoc frame onto the ProjectAAL host. That is handled by the navigation guard
  // (src/lib/previewNavigation.ts, injected as its own <script> below) —
  // it also covers unmatched routes, external links, and forms, which a
  // click-only handler here could not.

  // Listen for check-errors requests from parent
  window.addEventListener('message', function(event) {
    // No-op: Lovable wrapper sends this; ignore to keep console clean
    if (event.data && event.data.type === 'RESET_BLANK_CHECK') {
      return;
    }
    if (event.data && event.data.type === 'check-errors') {
      var errors = (window.__previewErrors || []).slice(0, 5);
      window.parent.postMessage({ type: 'preview-errors', errors: errors }, '*');
      window.__previewErrors = [];
    }
    // Visual design review: rasterise the rendered app and hand the image
    // back to the parent, which forwards it to a vision model. html2canvas
    // is loaded lazily here (never on the normal preview path) so it costs
    // nothing unless the user explicitly asks for a review.
    if (event.data && event.data.type === 'capture-preview') {
      (function() {
        var width = event.data.width || 1280;
        function fail(reason) {
          window.parent.postMessage({ type: 'preview-capture', error: reason }, '*');
        }
        function render() {
          try {
            window.html2canvas(document.body, {
